// Generated by scaffold-page-from-story from user_stories/ADM-04-categories.yaml
// Story: US-ADM-04-CATEGORIES
// Role:  admin
// Feature: Category management
// Goal: As an operator I can create and reorder categories so that the home page strip reflects how we want the catalogue read.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// Restyled to mirror design/html/admin/ADM-04-categories.html. Scope-locked parts
// preserved: default export (AdminCategoryListPage), every data-testid, and the
// fetch wiring below (the data1 useEffect).
// Only the presentation was rebuilt to match the prototype, wiring the fetched
// categories into the shared DataTable / listing components.

import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { DataTable } from '~/components/data-table/DataTable';
import { RowSelect } from '~/components/listing/RowSelect';
import { RowActions } from '~/components/listing/RowActions';
import { BulkActions } from '~/components/listing/BulkActions';
import { EntityFormModal } from '~/components/listing/EntityFormModal';
import { useRowSelection } from '~/components/listing/useRowSelection';
import { SearchInput } from '~/components/atoms/SearchInput';

import { useAppDispatch } from '~/hooks/useAppDispatch';
import { listCategories, createCategory, updateCategory, deleteCategory } from '~/services/httpServices/adminConsoleService';
import { toast } from '~/lib/toast';

import type { DataTableColumn } from '~/components/data-table/DataTable';
import { Plus } from 'lucide-react';
import type { AdminCategoryRow } from '~/types/view-models';
import { getApiErrorMessage } from '~/utils/apiError';
import { FieldError, fieldProps } from '~/components/shared/FieldError';
import { number, readForm, required, slug as slugRule, validate, type FieldErrors } from '~/utils/validation';
import { PageHeading } from '~/components/shared/Placeholder';
import { useSlugField } from '~/hooks/useSlugField';
import { ImagePickerField } from '~/components/shared/ImagePickerField';
import { datedFilename, downloadCsv } from '~/utils/csv';

/** A category row as rendered by the listing. The index signature keeps it
 *  assignable to DataTable's `Record<string, unknown>` constraint while the
 *  named fields document what the columns read. */

/** Pull the category array out of whatever envelope the API returns (bare array,
 *  { data }, { items }, { results }, { categories }). Unknown shapes collapse to []. */
function extractRows(d: unknown): AdminCategoryRow[] {
  let arr: unknown = d;
  if (d && typeof d === 'object' && !Array.isArray(d)) {
    const obj = d as Record<string, unknown>;
    arr = obj.data ?? obj.items ?? obj.results ?? obj.categories ?? [];
  }
  if (!Array.isArray(arr)) return [];
  return arr.map((item) => {
    const rec = item && typeof item === 'object' ? (item as Record<string, unknown>) : {};
    return { ...rec, id: String(rec.id ?? rec._id ?? '') } as AdminCategoryRow;
  });
}

function numDisplay(value: unknown): string {
  if (value === null || value === undefined || value === '') return '';
  const n = Number(value);
  return Number.isNaN(n) ? '' : new Intl.NumberFormat().format(n);
}

export default function AdminCategoryListPage() {
  const { t } = useTranslation('common');
  const dispatch = useAppDispatch();
  // This page renders only behind the admin route guard (AdminLayout / auth:admin),
  // so the operator is always an administrator. Mutating actions are gated on it so
  // the intent stays explicit if that guard is ever relaxed.
  const isAdmin = true;

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(listCategories(undefined)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, reloadKey]);

  // --- Presentation state (added by convert-pages) -------------------------
  const [modalOpen, setModalOpen] = useState<boolean>(false);
  const [editing, setEditing] = useState<AdminCategoryRow | null>(null);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [removedIds, setRemovedIds] = useState<string[]>([]);

  const allCategories = extractRows(data1).filter((c) => !removedIds.includes(c.id));
  const term = searchTerm.trim().toLowerCase();
  const categories = term
    ? allCategories.filter(
        (c) =>
          String(c.name ?? '').toLowerCase().includes(term) ||
          String(c.slug ?? '').toLowerCase().includes(term),
      )
    : allCategories;

  const activeCount = categories.filter((c) => c.isActive !== false).length;
  const courseTotal = categories.reduce((sum, c) => sum + (Number(c.courseCount) || 0), 0);
  const stats = [
    { key: 'total', label: t('admin.categories.stat.total', { defaultValue: 'Categories' }), value: categories.length },
    { key: 'active', label: t('admin.categories.stat.active', { defaultValue: 'Active' }), value: activeCount },
    { key: 'courses', label: t('admin.categories.stat.courses', { defaultValue: 'Courses' }), value: courseTotal },
  ];

  const sel = useRowSelection(categories.map((c) => c.id));

  // The slug writes itself from the name until the operator edits it.
  const slugField = useSlugField();
  const [icon, setIcon] = useState<string>('');

  function openCreate() {
    setEditing(null);
    slugField.reset();
    setIcon('');
    setModalOpen(true);
  }
  function openEdit(row: AdminCategoryRow) {
    setEditing(row);
    slugField.reset(row.slug ? String(row.slug) : '');
    setIcon(row.iconUrl ? String(row.iconUrl) : '');
    setModalOpen(true);
  }
  async function handleModalSubmit(form: FormData) {
    // A blank name used to create a category with no name in it — the field is
    // only added to the body `if (name)`, so an empty one was simply omitted
    // and the API had nothing to reject.
    const found = validate(
      { name: form.get('name'), slug: form.get('slug'), displayOrder: form.get('displayOrder') },
      {
        name: [required(t('admin.categories.field.name', { defaultValue: 'Name' }))],
        slug: [slugRule(t('admin.categories.field.slug', { defaultValue: 'Slug' }))],
        displayOrder: [number(t('admin.categories.field.displayOrder', { defaultValue: 'Display order' }), { min: 0 })],
      },
    );
    if (Object.keys(found).length) {
      toast.error(Object.values(found)[0]);
      return;
    }
    const body: Record<string, unknown> = {};
    const name = String(form.get('name') ?? '').trim();
    const slug = String(form.get('slug') ?? '').trim();
    const order = form.get('displayOrder');
    const active = form.get('isActive');
    if (name) body.name = name;
    if (slug) body.slug = slug;
    if (order !== null && String(order) !== '') body.displayOrder = Number(order);
    if (active !== null) body.isActive = String(active) === 'Active';
    // Sent even when empty, so clearing the image actually clears it.
    if (editing || icon) body.iconUrl = icon;
    if (editing) {
      await updateCategory(editing.id, body);
      toast.success(t('admin.categories.updated', { defaultValue: 'Category updated' }));
    } else {
      await createCategory(body);
      toast.success(t('admin.categories.created', { defaultValue: 'Category created' }));
    }
    reload();
  }
  async function handleDelete(row: AdminCategoryRow) {
    try {
      await deleteCategory(row.id);
      setRemovedIds((prev) => [...prev, row.id]);
      toast.success(t('admin.categories.deleted', { defaultValue: 'Category deleted' }));
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('admin.categories.deleteFailed', { defaultValue: 'Could not delete the category' })));
    }
  }
  function handleBulkExport() {
    downloadCsv(datedFilename('categories'), categories.filter((row) => sel.isSelected(row.id)), [
      { header: 'Name', value: (row) => row.name ?? '' },
      { header: 'Slug', value: (row) => row.slug ?? '' },
      { header: 'Order', value: (row) => row.displayOrder ?? '' },
      { header: 'Courses', value: (row) => row.courseCount ?? '' },
      { header: 'Active', value: (row) => (row.isActive === false ? 'Hidden' : 'Active') },
    ]);
  }
  async function handleBulkDelete() {
    const ids = sel.selected;
    try {
      await Promise.all(ids.map((id) => deleteCategory(id)));
      setRemovedIds((prev) => [...prev, ...ids]);
      toast.success(t('admin.categories.bulkDeleted', { defaultValue: 'Selected categories deleted' }));
      sel.clear();
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('admin.categories.bulkDeleteFailed', { defaultValue: 'Could not delete the selected categories' })));
    }
  }

  function renderActive(row: AdminCategoryRow) {
    const active = row.isActive !== false;
    const cls = active
      ? 'bg-emerald-50 text-emerald-700 ring-emerald-600/20'
      : 'bg-muted text-muted-foreground ring-border';
    const label = active
      ? t('admin.categories.status.active', { defaultValue: 'Active' })
      : t('admin.categories.status.hidden', { defaultValue: 'Hidden' });
    return (
      <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ring-1 ring-inset ${cls}`}>
        {label}
      </span>
    );
  }

  const columns: DataTableColumn<AdminCategoryRow>[] = [
    {
      key: 'select',
      label: '',
      width: '40px',
      render: (row) => (
        <RowSelect
          checked={sel.isSelected(row.id)}
          onChange={() => sel.toggle(row.id)}
          label={t('actions.selectRow', { defaultValue: 'Select row' })}
          testId={`adm-04-categories-row-${row.id}`}
        />
      ),
    },
    {
      key: 'name',
      label: t('admin.categories.col.name', { defaultValue: 'Name' }),
      sortable: true,
      render: (row) => <span className="font-medium text-foreground">{String(row.name ?? '')}</span>,
    },
    {
      key: 'slug',
      label: t('admin.categories.col.slug', { defaultValue: 'Slug' }),
      sortable: true,
      render: (row) => <span className="text-muted-foreground">{String(row.slug ?? '')}</span>,
    },
    { key: 'courseCount', label: t('admin.categories.col.courses', { defaultValue: 'Courses' }), sortable: true, render: (row) => numDisplay(row.courseCount) },
    { key: 'displayOrder', label: t('admin.categories.col.order', { defaultValue: 'Order' }), sortable: true, render: (row) => numDisplay(row.displayOrder) },
    { key: 'isActive', label: t('admin.categories.col.active', { defaultValue: 'Active' }), sortable: true, render: (row) => renderActive(row) },
  ];

  const bulkActions = isAdmin
    ? [
        { label: t('actions.export', { defaultValue: 'Export' }), onSelect: handleBulkExport },
        { label: t('actions.delete', { defaultValue: 'Delete' }), destructive: true, onSelect: handleBulkDelete },
      ]
    : [];

  return (
    <div className="w-full" data-testid="adm-04-categories-page">
      <header className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <PageHeading
        eyebrow={t("admin.categories.eyebrow", { defaultValue: "Catalogue" })}
        title={t("admin.categories.title", { defaultValue: "Categories" })}
        hint={t("admin.categories.hint", { defaultValue: "How the catalogue is organised." })}
        testId="adm-04-categories-heading"
      />
        </div>
      </header>

      <main className="space-y-6" data-testid="adm-04-categories-main">
        <section className="rounded-[var(--radius-lg)] border border-border bg-card shadow-sm" data-testid="adm-04-categories-ac-1">
          {/* toolbar: search + new category */}
          <div className="flex flex-wrap items-center gap-3 border-b border-border p-4">
            <div className="min-w-[240px] flex-1" data-component="search-bar">
              <SearchInput
                placeholder={t('admin.categories.searchPlaceholder', { defaultValue: 'Search' })}
                onDebouncedChange={setSearchTerm}
                testId="adm-04-categories-search"
              />
            </div>
            {isAdmin && (
              <button
                type="button"
                onClick={openCreate}
                data-testid="adm-04-categories-create"
                className="inline-flex h-10 items-center gap-2 rounded-md bg-[var(--c-primary)] px-4 text-sm font-medium text-[var(--c-on-primary)] transition-colors hover:bg-[var(--c-primary-active)]"
              >
                <Plus className="h-4 w-4" aria-hidden="true" />
                {t('admin.categories.new', { defaultValue: 'New category' })}
              </button>
            )}
          </div>

          {/* summary stats derived from the loaded categories */}
          {!loading1 && !error1 && (
            <div className="grid grid-cols-1 gap-4 border-b sm:grid-cols-3 border-border p-4" data-testid="adm-04-categories-ac-1-kpis">
              {stats.map((s) => (
                <div key={s.key} data-testid={`adm-04-categories-ac-1-kpi-${s.key}`} className="rounded-lg bg-muted/40 p-3">
                  <p className="text-xs text-muted-foreground">{s.label}</p>
                  <p className="mt-1 text-2xl font-semibold text-foreground">{new Intl.NumberFormat().format(s.value)}</p>
                </div>
              ))}
            </div>
          )}

          {/* selection + bulk actions */}
          <div className="flex flex-wrap items-center gap-4 px-4 py-2">
            <label className="flex items-center gap-2 text-sm text-muted-foreground">
              <RowSelect
                checked={sel.allSelected}
                indeterminate={sel.someSelected}
                onChange={sel.toggleAll}
                label={t('actions.selectAll', { defaultValue: 'Select all' })}
                testId="adm-04-categories-selectall"
              />
              {t('admin.categories.selectAll', { defaultValue: 'Select all' })}
            </label>
            <div data-component="bulk-actions">
              <BulkActions testId="adm-04-categories-list" count={sel.count} onClear={sel.clear} actions={bulkActions} />
            </div>
          </div>

          <div className="p-4 pt-0">
            {loading1 && (
              <div className="p-6 text-sm text-muted-foreground" data-testid="adm-04-categories-ac-1-loading">
                {t('actions.loading', { defaultValue: 'Loading…' })}
              </div>
            )}
            {error1 && (
              <div className="p-6 text-sm text-destructive" data-testid="adm-04-categories-ac-1-error">
                {t('admin.categories.loadError', { defaultValue: 'Unable to load categories' })}
              </div>
            )}
            {!loading1 && !error1 && (
              <div data-listing="writable" data-component="data-table">
                <DataTable
                  data={categories}
                  columns={columns}
                  rowKey={(row) => row.id}
                  rowAction={(row) => (
                    <span data-component="row-actions">
                      <RowActions
                        testId={`adm-04-categories-row-${row.id}`}
                        onEdit={isAdmin ? () => openEdit(row) : undefined}
                        onDelete={isAdmin ? () => handleDelete(row) : undefined}
                      />
                    </span>
                  )}
                  testId="adm-04-categories-list"
                  emptyMessage={t('admin.categories.empty', { defaultValue: 'No categories yet' })}
                />
              </div>
            )}
          </div>
        </section>

      </main>

      {/* Create / edit modal — mirrors the prototype's entity-form-modal. */}
      <div data-component="entity-form-modal">
        <EntityFormModal
          open={modalOpen}
          entityLabel={t('admin.categories.entity', { defaultValue: 'Category' })}
          initialValues={editing ?? undefined}
          onClose={() => setModalOpen(false)}
          onSubmit={handleModalSubmit}
          testId="adm-04-categories-form"
        >
          <div key={editing?.id ?? 'new'} className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.categories.field.name', { defaultValue: 'Name' })}</span>
              <input
                name="name"
                type="text"
                defaultValue={editing?.name ? String(editing.name) : ''}
                onChange={(e) => slugField.follow(e.target.value)}
                data-testid="adm-04-categories-field-name"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              />
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.categories.field.slug', { defaultValue: 'Slug' })}</span>
              <input
                name="slug"
                type="text"
                value={slugField.value}
                onChange={slugField.onChange}
                data-testid="adm-04-categories-field-slug"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              />
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.categories.field.order', { defaultValue: 'Order' })}</span>
              <input
                name="displayOrder"
                type="number"
                defaultValue={editing?.displayOrder != null ? String(editing.displayOrder) : ''}
                data-testid="adm-04-categories-field-order"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              />
            </label>
            <ImagePickerField
              name="iconUrl"
              label={t('admin.categories.field.icon', { defaultValue: 'Image' })}
              value={icon}
              onChange={setIcon}
              hint={t('admin.categories.field.iconHint', { defaultValue: 'Shown on the category tile. Cropped to a square.' })}
              labels={{
                choose: t('admin.categories.field.iconChoose', { defaultValue: 'Choose image' }),
                working: t('actions.saving', { defaultValue: 'Saving…' }),
                remove: t('actions.remove', { defaultValue: 'Remove' }),
              }}
              className="sm:col-span-2"
              labelClassName="text-sm font-medium text-foreground"
              testId="adm-04-categories-field-icon"
            />
            <label className="flex flex-col gap-1">
              <span className="text-sm font-medium text-foreground">{t('admin.categories.field.active', { defaultValue: 'Active' })}</span>
              <select
                name="isActive"
                defaultValue={editing && editing.isActive === false ? 'Hidden' : 'Active'}
                data-testid="adm-04-categories-field-active"
                className="h-10 rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"
              >
                <option value="Active">{t('admin.categories.status.active', { defaultValue: 'Active' })}</option>
                <option value="Hidden">{t('admin.categories.status.hidden', { defaultValue: 'Hidden' })}</option>
              </select>
            </label>
          </div>
        </EntityFormModal>
      </div>
    </div>
  );
}
